import type {SessionEntry} from './session.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export type IncomingMessage = UserMessagePayload | PingMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage;

export {ErrorCodes} from './session.js';
import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });
});
