describe('validating a list_sessions frame', () => {
  it('accepts a list_sessions frame, forwarding limit and before and dropping a client userId', () => {
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const results = [
      validateMessage({type: 'list_sessions'}),
      validateMessage({type: 'list_sessions', limit: 0, before: {updatedAt: 1767225900000, sessionId: 's3'}}),
      validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'}),
    ];

    expect(results).toEqual([
      {valid: true, data: {type: 'list_sessions'}},
      {valid: true, data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1767225900000, sessionId: 's3'}}},
      {valid: true, data: {type: 'list_sessions', limit: 10, before}},
    ]);
  });

  it('rejects a list_sessions frame whose limit or before is malformed, naming the field', () => {
    const bad = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: null},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: Number.NaN, sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const errors = bad.map(frame => {
      const result = validateMessage(frame);
      return result.valid ? 'accepted' : /limit|before/.test(result.error);
    });

    expect(errors).toEqual(Array(bad.length).fill(true));
  });
});

